package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	r := bufio.NewReaderSize(os.Stdin, 1<<20)
	line, _ := r.ReadString('\n')
	k, _ := strconv.Atoi(strings.TrimSpace(line))
	data, _ := io.ReadAll(r)
	cnt := map[string]int{}
	start := -1
	isAl := func(c byte) bool {
		return c >= '0' && c <= '9' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z'
	}
	for i := 0; i <= len(data); i++ {
		if i < len(data) && isAl(data[i]) {
			if start < 0 {
				start = i
			}
		} else if start >= 0 {
			cnt[strings.ToLower(string(data[start:i]))]++
			start = -1
		}
	}
	type kv struct {
		w string
		c int
	}
	var a []kv
	for w, c := range cnt {
		a = append(a, kv{w, c})
	}
	sort.Slice(a, func(i, j int) bool {
		if a[i].c != a[j].c {
			return a[i].c > a[j].c
		}
		return a[i].w < a[j].w
	})
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < len(a) && i < k; i++ {
		fmt.Fprintf(w, "%s %d\n", a[i].w, a[i].c)
	}
}
